#!/usr/bin/env Rscript
options(warn=2);args<-commandArgs(trailingOnly=TRUE);if(length(args)!=4L)stop("usage: run_mv17c_calibration_worker.R <matrix-rds> <null-family-or-observed> <seed> <output-rds>")
matrix_path<-normalizePath(args[[1]],mustWork=TRUE);family<-args[[2]];seed<-as.integer(args[[3]]);output<-args[[4]];if(file.exists(output))stop("MV17-C worker output exists")
source("R/mv17_null_models.R");source("R/mv17_calibration.R");source("R/mv17_localization.R");x<-readRDS(matrix_path);x<-as.matrix(x);if(anyNA(x)||any(!is.finite(x)))stop("MV17-C non-finite matrix")
registry<-mv17b_null_registry_v1();if(family=="observed")z<-x else {hit<-registry[registry$null_family==family,,drop=FALSE];if(nrow(hit)!=1L)stop("MV17-C unknown null family");z<-get(hit$function_name,mode="function")(x,seed)}
diagram<-as.data.frame(ripserr::vietoris_rips(z,max_dim=1L,threshold=Inf));metrics<-do.call(rbind,lapply(0:1,function(d)mv17c_diagram_metrics_v1(diagram,d)));h0<-diagram[diagram[,1]==0&is.finite(diagram[,3])&diagram[,3]>diagram[,2],,drop=FALSE];mst<-mv17d_h0_mergers_v1(z);h0_error<-if(nrow(h0)==nrow(mst))max(abs(sort(h0[,3])-sort(mst$death)))else Inf;if(!is.finite(h0_error)||h0_error>1e-8)stop("MV17-C H0 MST oracle failed")
out<-list(contract_id="mv17c_worker_result_v1",null_family=family,seed=seed,points=nrow(z),coordinates=ncol(z),matrix_sha256=digest::digest(matrix_path,algo="sha256",file=TRUE,serialize=FALSE),metrics=metrics,h0_mst_maximum_absolute_error=h0_error,finite=all(is.finite(metrics$value)),labels_opened=FALSE,outcomes_opened=FALSE);if(!out$finite)stop("MV17-C non-finite metrics");dir.create(dirname(output),recursive=TRUE,showWarnings=FALSE);tmp<-paste0(output,".partial");saveRDS(out,tmp,version=3);if(!file.rename(tmp,output))stop("MV17-C atomic promotion failed")
